using Pooshit.Json;

namespace Backend.tests.Fixtures;

/// <summary>
/// reference tokens and vectors generated by <c>EmbeddingReference/generate_reference.py</c>
/// </summary>
public class EmbeddingReference {
    /// <summary>
    /// Hugging Face repository the reference was generated from
    /// </summary>
    public string Model { get; set; } = "";

    /// <summary>
    /// revision of <see cref="Model"/>
    /// </summary>
    public string Revision { get; set; } = "";

    /// <summary>
    /// prompts with their reference results
    /// </summary>
    public EmbeddingReferenceEntry[] Entries { get; set; } = [];

    /// <summary>
    /// reads the reference file copied next to the test assembly
    /// </summary>
    /// <returns>the reference</returns>
    public static EmbeddingReference Load() {
        return Json.Read<EmbeddingReference>(File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "EmbeddingReference", "embedding-reference.json")));
    }
}
